16	// These tests pin ListCatalogUnderContext (DEVDESK-579 step 1): the catalog of
17	// a Nexus group member is read at /v2/<prefix>/_catalog. Names come back as the
18	// server sent them (not prefixed); rebuilding "<prefix>/<name>" is the
19	// caller's job. The walk keeps every guard of ListCatalogContext (same origin,
20	// bounded pages, no credentials to another origin), the prefix segments are
21	// escaped, and an unsafe prefix is refused before any request.
22	
23	// requestLog records the raw request target (path and query, as sent on the
24	// wire) of every request a test server receives, and the Authorization header
25	// of each.
26	type requestLog struct {
27		mu    sync.Mutex
28		uris  []string
29		auths []string
30	}
31	
32	func (l *requestLog) add(r *http.Request) {
33		l.mu.Lock()
34		defer l.mu.Unlock()
35		l.uris = append(l.uris, r.RequestURI)
36		l.auths = append(l.auths, r.Header.Get("Authorization"))
37	}
38	
39	func (l *requestLog) URIs() []string {
40		l.mu.Lock()
41		defer l.mu.Unlock()
42		return append([]string(nil), l.uris...)
43	}
44	
45	func (l *requestLog) Auths() []string {
46		l.mu.Lock()
47		defer l.mu.Unlock()
48		return append([]string(nil), l.auths...)
49	}
50	
51	// rawPath is the path part of a request target.
52	func rawPath(uri string) string {
53		p, _, _ := strings.Cut(uri, "?")
54		return p
55	}
