57	func TestListCatalogUnderContextPath(t *testing.T) {
58		tests := []struct {
59			name       string
60			prefix     string
61			wantRaw    string // exact path on the wire
62			wantDecode string // path as the server decodes it
63		}{
64			{"empty prefix is the root catalog", "", "/v2/_catalog", "/v2/_catalog"},
65			{"one segment", "docker-hosted", "/v2/docker-hosted/_catalog", "/v2/docker-hosted/_catalog"},
66			{"proxy member", "docker-proxy", "/v2/docker-proxy/_catalog", "/v2/docker-proxy/_catalog"},
67			{"two segments", "a/b", "/v2/a/b/_catalog", "/v2/a/b/_catalog"},
68			{"three segments", "a/b/c", "/v2/a/b/c/_catalog", "/v2/a/b/c/_catalog"},
69			{"dot and dash inside a segment are kept", "my-repo.v2", "/v2/my-repo.v2/_catalog", "/v2/my-repo.v2/_catalog"},
70			{"space is escaped", "my repo", "/v2/my%20repo/_catalog", "/v2/my repo/_catalog"},
71			{"space in each segment", "a b/c d", "/v2/a%20b/c%20d/_catalog", "/v2/a b/c d/_catalog"},
72			{"percent is escaped", "50%", "/v2/50%25/_catalog", "/v2/50%/_catalog"},
73			{"an encoded slash stays one segment", "a%2Fb", "/v2/a%252Fb/_catalog", "/v2/a%2Fb/_catalog"},
74			{"an encoded dot-dot is not decoded", "%2e%2e", "/v2/%252e%252e/_catalog", "/v2/%2e%2e/_catalog"},
75			{"question mark does not start a query", "a?b", "/v2/a%3Fb/_catalog", "/v2/a?b/_catalog"},
76			{"hash does not start a fragment", "a#b", "/v2/a%23b/_catalog", "/v2/a#b/_catalog"},
77			{"non-ASCII is escaped", "café", "/v2/caf%C3%A9/_catalog", "/v2/café/_catalog"},
78		}
79		for _, tt := range tests {
80			t.Run(tt.name, func(t *testing.T) {
81				var log requestLog
82				var decoded atomic.Value
83				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
84					log.add(r)
85					decoded.Store(r.URL.Path)
86					_, _ = fmt.Fprint(w, catalogBody("api", "team/api"))
87				}))
88				defer srv.Close()
89	
90				names, truncated, err := ListCatalogUnderContext(context.Background(), srv.URL, tt.prefix, "", "", 10, 1000)
91				if err != nil {
92					t.Fatal(err)
93				}
94				// Names are the server's own: never prefixed by this function.
95				if got, want := strings.Join(names, ","), "api,team/api"; got != want {
96					t.Errorf("names = %s, want %s", got, want)
97				}
98				if truncated {
99					t.Error("truncated = true, want false")
100				}
101				uris := log.URIs()
102				if len(uris) != 1 {
103					t.Fatalf("requests = %v, want exactly one", uris)
104				}
105				if got := rawPath(uris[0]); got != tt.wantRaw {
106					t.Errorf("wire path = %q, want %q", got, tt.wantRaw)
107				}
108				if got, _ := decoded.Load().(string); got != tt.wantDecode {
109					t.Errorf("decoded path = %q, want %q", got, tt.wantDecode)
110				}
111				// The page size is the only query parameter, whatever the prefix held.
112				if _, q, _ := strings.Cut(uris[0], "?"); q != "n=1000" {
113					t.Errorf("query = %q, want n=1000", q)
114				}
115			})
116		}
117	}
