155	func TestListCatalogUnderContextRefusesUnsafePrefix(t *testing.T) {
156		const user, pass = "svc-user-4711", "s3cret-pass-4711"
157		for _, tt := range []struct {
158			name   string
159			prefix string
160		}{
161			{"dot-dot", ".."},
162			{"dot-dot last", "a/.."},
163			{"dot-dot first", "../a"},
164			{"dot-dot middle", "a/../b"},
165			{"dot-dot inside a segment", "a..b"},
166			{"single dot", "."},
167			{"dot first", "./a"},
168			{"dot middle", "a/./b"},
169			{"empty segment in the middle", "a//b"},
170			{"leading slash", "/docker-hosted"},
171			{"trailing slash", "docker-hosted/"},
172			{"only a slash", "/"},
173			{"backslash", `a\b`},
174			{"leading backslash", `\docker-hosted`},
175			{"NUL byte", "a\x00b"},
176			{"NUL alone", "\x00"},
177		} {
178			t.Run(tt.name, func(t *testing.T) {
179				var hits atomic.Int32
180				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
181					hits.Add(1)
182					_, _ = fmt.Fprint(w, catalogBody("api"))
183				}))
184				defer srv.Close()
185	
186				names, truncated, err := ListCatalogUnderContext(context.Background(), srv.URL, tt.prefix, user, pass, 10, 1000)
187				if err == nil {
188					t.Fatal("err = nil, want a refusal")
189				}
190				if hits.Load() != 0 {
191					t.Errorf("requests = %d, want 0: an unsafe prefix must be refused before any request", hits.Load())
192				}
193				if names != nil || truncated {
194					t.Errorf("names = %v truncated = %v, want nil false", names, truncated)
195				}
196				var se *StatusError
197				if errors.As(err, &se) {
198					t.Errorf("err = %v is a *StatusError, want a plain refusal (nothing was asked)", err)
199				}
200				if strings.TrimSpace(err.Error()) == "" {
201					t.Error("err message is empty, want a readable one")
202				}
203				// The refusal never echoes a secret.
204				for _, secret := range []string{user, pass} {
205					if strings.Contains(err.Error(), secret) {
206						t.Errorf("err = %q echoes %q", err, secret)
207					}
208				}
209			})
210		}
211	}
