502	// ListCatalogContext is ListCatalogUnderContext with an empty prefix: same
503	// requests, same result, same error, so the existing callers see no change.
504	func TestListCatalogContextDelegatesWithEmptyPrefix(t *testing.T) {
505		type outcome struct {
506			names     []string
507			truncated bool
508			errText   string
509			status    int
510		}
511		run := func(fn func(url string) ([]string, bool, error), handler http.HandlerFunc) (outcome, []string) {
512			var log requestLog
513			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
514				log.add(r)
515				handler(w, r)
516			}))
517			defer srv.Close()
518			names, truncated, err := fn(srv.URL)
519			o := outcome{names: names, truncated: truncated}
520			if err != nil {
521				o.errText = err.Error()
522				var se *StatusError
523				if errors.As(err, &se) {
524					o.status = se.Code
525				}
526			}
527			return o, log.URIs()
528		}
529	
530		paged := func(w http.ResponseWriter, r *http.Request) {
531			switch r.URL.Query().Get("last") {
532			case "":
533				w.Header().Set("Link", `</v2/_catalog?n=2&last=b>; rel="next"`)
534				_, _ = fmt.Fprint(w, catalogBody("a", "b"))
535			default:
536				_, _ = fmt.Fprint(w, catalogBody("c"))
537			}
538		}
539		endless := func(w http.ResponseWriter, r *http.Request) {
540			w.Header().Set("Link", `</v2/_catalog?n=2&last=`+r.URL.Query().Get("last")+`x>; rel="next"`)
541			_, _ = fmt.Fprint(w, catalogBody("a", "b"))
542		}
543		notFound := func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusNotFound) }
544		undecodable := func(w http.ResponseWriter, _ *http.Request) { _, _ = fmt.Fprint(w, `<html>not json`) }
545	
546		for _, tt := range []struct {
547			name    string
548			handler http.HandlerFunc
549		}{
550			{"paged walk", paged},
551			{"truncated walk", endless},
552			{"404", notFound},
553			{"undecodable body", undecodable},
554		} {
555			t.Run(tt.name, func(t *testing.T) {
556				viaLegacy, legacyURIs := run(func(url string) ([]string, bool, error) {
557					return ListCatalogContext(context.Background(), url, "user", "pass", 3, 2)
558				}, tt.handler)
559				viaUnder, underURIs := run(func(url string) ([]string, bool, error) {
560					return ListCatalogUnderContext(context.Background(), url, "", "user", "pass", 3, 2)
561				}, tt.handler)
562	
563				if !reflect.DeepEqual(viaLegacy, viaUnder) {
564					t.Errorf("results differ:\n ListCatalogContext          = %+v\n ListCatalogUnderContext(\"\") = %+v", viaLegacy, viaUnder)
565				}
566				if !reflect.DeepEqual(legacyURIs, underURIs) {
567					t.Errorf("requests differ:\n ListCatalogContext          = %v\n ListCatalogUnderContext(\"\") = %v", legacyURIs, underURIs)
568				}
569				if len(underURIs) == 0 || rawPath(underURIs[0]) != "/v2/_catalog" {
570					t.Errorf("first request = %v, want /v2/_catalog", underURIs)
571				}
572			})
573		}
574	}
